draw:
var k = 8.99e9;
var q = 3e-9;                 // fixed 3 nC
var h = p.height;             // cm
var plateY = H * 0.74;
var scale = (plateY - H * 0.10) / 6;   // pixels per cm, 6 cm fits
var cx = W * 0.5;
var cy = plateY - h * scale;
var iy = plateY + h * scale;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines traced from the charge in the real half-space
var N = 16;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.1;
for (var i = 0; i < N; i++) {
  var a = -Math.PI * 0.5 + (i + 0.5) * (2 * Math.PI / N);
  var x = cx + Math.cos(a) * 9;
  var y = cy + Math.sin(a) * 9;
  ctx.beginPath();
  ctx.moveTo(x, y);
  for (var s = 0; s < 500; s++) {
    var dx1 = x - cx, dy1 = y - cy;
    var r1 = Math.sqrt(dx1 * dx1 + dy1 * dy1); if (r1 < 1) r1 = 1;
    var dx2 = x - cx, dy2 = y - iy;
    var r2 = Math.sqrt(dx2 * dx2 + dy2 * dy2); if (r2 < 1) r2 = 1;
    var ex = dx1 / (r1 * r1 * r1) - dx2 / (r2 * r2 * r2);
    var ey = dy1 / (r1 * r1 * r1) - dy2 / (r2 * r2 * r2);
    var m = Math.sqrt(ex * ex + ey * ey); if (m === 0) break;
    x += 2.2 * ex / m;
    y += 2.2 * ey / m;
    if (y >= plateY || x < 0 || x > W || y < 0) break;
    ctx.lineTo(x, y);
  }
  ctx.stroke();
}

// the plate
ctx.fillStyle = C.faint;
ctx.fillRect(0, plateY, W, H * 0.10);
ctx.strokeStyle = C.rule;
ctx.lineWidth = 1.5;
ctx.beginPath(); ctx.moveTo(0, plateY); ctx.lineTo(W, plateY); ctx.stroke();

// induced surface charge density, sigma(x) proportional to -h/(x^2+h^2)^1.5
ctx.strokeStyle = C.accent;
ctx.lineWidth = 1.5;
ctx.beginPath();
var peak = 1 / (h * h);
for (var xi = 0; xi <= W; xi += 3) {
  var xm = (xi - cx) / scale;
  var val = h / Math.pow(xm * xm + h * h, 1.5);
  var yy = plateY + (val / peak) * (H * 0.09);
  if (xi === 0) ctx.moveTo(xi, yy); else ctx.lineTo(xi, yy);
}
ctx.stroke();

// the real charge
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, cy, 8, 0, 6.2832); ctx.fill();
ctx.fillStyle = C.paper;
ctx.textAlign = "center";
ctx.fillText("+", cx, cy + 4);

// the image charge, ghosted
ctx.strokeStyle = C.accent;
ctx.setLineDash([3, 3]);
ctx.lineWidth = 1.2;
ctx.beginPath(); ctx.arc(cx, iy, 8, 0, 6.2832); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx, cy + 9); ctx.lineTo(cx, iy - 9); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.accent;
ctx.fillText("-", cx, iy + 4);

// labels
ctx.fillStyle = C.ink;
ctx.textAlign = "left";
ctx.fillText("+q at h", cx + 14, cy + 4);
ctx.fillText("image -q at -h (not real)", cx + 14, iy + 4);
ctx.fillText("grounded conductor, V = 0", 8, plateY + H * 0.10 - 6);
ctx.fillStyle = C.accent;
ctx.fillText("induced surface charge", 8, 16);

var F = k * q * q / (4 * h * h * 1e-4);
var Wk = k * q * q / (4 * h * 1e-2);
out.note = "h = " + h.toFixed(1) + " cm, attraction F = " + (F * 1e9).toFixed(2) + " nN, work to remove it to infinity = " + (Wk * 1e9).toFixed(3) + " nJ";
